def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 5 != 1 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[1:] + [filtered_rows[0]]

    group_map = {}
    for row in rotated_rows:
        group = row[0]
        score = row[1]
        timestamp = row[2]
        name = row[3]

        if group not in group_map:
            group_map[group] = (score, timestamp, name)
        else:
            existing_score, existing_timestamp, existing_name = group_map[group]
            if score > existing_score:
                group_map[group] = (score, timestamp, name)
            elif score == existing_score and timestamp < existing_timestamp:
                group_map[group] = (score, timestamp, name)
            elif score == existing_score and timestamp == existing_timestamp and name > existing_name:
                group_map[group] = (score, timestamp, name)

    result = []
    for group in sorted(group_map.keys()):
        score, timestamp, name = group_map[group]
        result.append([group, name])

    return result

